#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string s;
    std::cin >> s;
    std::sort(s.begin(), s.end());          // next_permutation starts from sorted

    std::vector<std::string> out;
    do { out.push_back(s); }
    while (std::next_permutation(s.begin(), s.end()));

    std::cout << out.size() << '\n';
    for (const std::string& p : out) std::cout << p << '\n';
}
